INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3b20382c-5bb4-463d-96aa-121d6effe2ee', '03ae4e5e-5658-44e6-82c3-bf8d03c1b2fe', 0, 'Salting — appending or prepending a unique, random value (the "salt") to each password BEFORE hashing, so that even two identical plaintext passwords produce completely different hash outputs once each user''s unique salt is combined in; the salt is stored alongside the hash (it doesn''t need to be secret) specifically to allow verification later.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e613539-1662-4dcb-bce5-ccb1e1e05217', '03ae4e5e-5658-44e6-82c3-bf8d03c1b2fe', 1, 'Using a stronger hash algorithm alone (e.g., switching from MD5 to SHA-256) fully solves this problem, since a stronger algorithm always produces different outputs for identical inputs.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a7e28555-87df-4240-b2f5-b98918f05466', '03ae4e5e-5658-44e6-82c3-bf8d03c1b2fe', 2, 'Encrypting the password with a shared symmetric key instead of hashing it is the correct fix, and produces different ciphertext for identical passwords with no additional technique needed.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('878f9e7f-6a0c-4d23-9707-d98195a48dcf', '03ae4e5e-5658-44e6-82c3-bf8d03c1b2fe', 3, 'This is not a real security concern, since identical hash values for identical passwords pose no risk of any kind.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fc290062-4057-4f75-88c4-1364eafab110', '37abbc72-f22a-4426-a168-c737cc751260', 0, 'Steganography — the practice of concealing a message or data WITHIN another, seemingly unrelated file or medium (an image, audio file, or similar), such that the existence of the hidden content itself is disguised, distinct from encryption, which protects a message''s CONTENT but doesn''t hide the fact that a (visibly encrypted) message exists at all.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f4bfada9-c99a-4f2b-b69b-df20cd3552bb', '37abbc72-f22a-4426-a168-c737cc751260', 1, 'Hashing, since hashing is the technique used to embed hidden messages within image pixel data.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('64e6c748-559d-4df9-b242-9ddc934b98fe', '37abbc72-f22a-4426-a168-c737cc751260', 2, 'Tailgating, since tailgating refers to hiding data within digital image files.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fbff3153-1ccf-4a8b-a2b9-8be33b91af42', '37abbc72-f22a-4426-a168-c737cc751260', 3, 'This technique does not exist; data cannot be hidden within an image file in a way that leaves the image visually unchanged.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e22d9fdd-03cb-4eea-aa62-afb33e597e0d', 'b21437a4-d4d6-422f-8d03-78b8ce70fcd2', 0, 'A DDoS (Distributed Denial of Service) attack — the "distributed" part specifically means the attack traffic originates from MANY different sources simultaneously (often a botnet of compromised devices), which is what makes it far harder to mitigate by simply blocking a single source IP the way a basic single-source DoS attack could be addressed.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc631d6d-2f68-4508-bd65-811d58f0bda3', 'b21437a4-d4d6-422f-8d03-78b8ce70fcd2', 1, 'A DDoS attack and a single-source DoS attack are fully identical in every respect, including mitigation approach, with no meaningful distinction.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b6b85401-a924-4ec8-9370-4a1e8353c4f7', 'b21437a4-d4d6-422f-8d03-78b8ce70fcd2', 2, 'This is SQL injection, since any attack causing a website to become unavailable is classified as SQL injection.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e803e490-a06b-4145-99f5-32186f0454fb', 'b21437a4-d4d6-422f-8d03-78b8ce70fcd2', 3, 'This scenario describes a physical security incident, unrelated to network-based attacks.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7dc40f8e-2b4e-49f7-b420-ac15fd5a72ac', '30ab90b1-e6e9-47f0-8b94-a9b2033bc88f', 0, 'A watering hole attack — compromising a legitimate third-party site the target group is known to frequently visit (rather than attacking the target directly), then waiting for victims to come to the compromised site on their own, exploiting the group''s established trust in that third-party destination.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('892c26bb-8cf6-4121-a098-2fa8d0ba9552', '30ab90b1-e6e9-47f0-8b94-a9b2033bc88f', 1, 'Whaling, since whaling refers to compromising any third-party website visited by employees.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7c9ba938-a0ad-4a85-9f6f-1181ad19d64c', '30ab90b1-e6e9-47f0-8b94-a9b2033bc88f', 2, 'Vishing, since vishing is defined as compromising a website rather than making a phone call.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('19bcf2de-6b45-4475-8fa5-b4a440e163b9', '30ab90b1-e6e9-47f0-8b94-a9b2033bc88f', 3, 'Tailgating, since tailgating describes compromising a third-party website to indirectly reach a target.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('86b85f05-5a76-4d2c-a1aa-82b4e1938ee0', '8f719f98-5166-4311-9982-79bb84ca9048', 0, 'Compensating controls — since the primary control (patching) is unavailable, apply alternative protective measures around the unpatchable system instead: network isolation/segmentation limiting what can reach it, strict access control, enhanced monitoring specifically for that system, and application allowlisting, reducing risk through layers OTHER than the unavailable patch itself.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('23fae09f-79d1-4e62-8bec-b8dafe5a296e', '8f719f98-5166-4311-9982-79bb84ca9048', 1, 'No security measures of any kind are possible or worthwhile once a system can no longer be patched; the system should simply be left completely unprotected.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a25370af-abc5-47ec-8d4d-b0cf931a6c0e', '8f719f98-5166-4311-9982-79bb84ca9048', 2, 'The only acceptable response is immediate physical destruction of the system, with no other option considered valid under any circumstance.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aa80ccc3-6421-411c-9cc5-60644ef94ea4', '8f719f98-5166-4311-9982-79bb84ca9048', 3, 'Unpatched legacy systems pose no elevated risk compared to fully current, patched systems.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('afe8cced-45de-47b4-ac39-3c7fb2d2cd03', '3637daa1-9ff3-40c6-a9cf-3767b2ebc3f6', 0, 'SASE (Secure Access Service Edge) — a converged architecture combining networking (SD-WAN-style connectivity) and multiple security functions (Zero Trust Network Access, secure web gateway, firewall-as-a-service, and more) into one cloud-delivered platform, applying consistent security policy close to the user/device regardless of location, rather than backhauling all traffic through a central on-premises security stack.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('37e4d348-efd1-46b9-b41d-1f2ed29022aa', '3637daa1-9ff3-40c6-a9cf-3767b2ebc3f6', 1, 'A DMZ, since DMZs are specifically designed to converge networking and security functions into one cloud-delivered platform for remote users.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0c445860-3757-4922-9b9c-34d6ceb2beb3', '3637daa1-9ff3-40c6-a9cf-3767b2ebc3f6', 2, 'A honeynet, since honeynets provide Zero Trust access control and secure web gateway filtering for distributed remote users.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('15cfeace-d7cf-46c7-bdaf-3e1b88f3431c', '3637daa1-9ff3-40c6-a9cf-3767b2ebc3f6', 3, 'This kind of converged, cloud-delivered security architecture does not exist as a recognized category.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1cbaa18e-bb41-4392-aa7e-2a19292641af', '508399f3-85bc-44b8-ad85-91539f81f733', 0, 'File Integrity Monitoring (FIM), which establishes a known-good baseline (often a cryptographic hash, covered earlier this paper) of critical files and directories, then continuously or periodically re-checks them, alerting when a monitored file''s hash changes — an unauthorized modification detectable even if the change itself doesn''t match any known malware signature.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('06f04937-fce5-443c-8694-fac3109fd750', '508399f3-85bc-44b8-ad85-91539f81f733', 1, 'A firewall alone, since firewalls monitor individual file contents for unauthorized modification by default.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a705f387-baf7-4834-960f-7e86fe9f4515', '508399f3-85bc-44b8-ad85-91539f81f733', 2, 'A VPN, since VPN''s core function is detecting unauthorized modification of critical system files.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0c416de8-77d1-4c32-a470-9e189bb3a508', '508399f3-85bc-44b8-ad85-91539f81f733', 3, 'No security technology can detect unauthorized file modification without a matching malware signature.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fbc42e65-e703-452f-9c52-0fa53af5d1c9', '505ba1a6-943b-43b6-9ca6-e8b3c75e14aa', 0, 'UEBA (User and Entity Behavior Analytics), which builds a baseline of NORMAL behavior for each user/entity (typical login times, typical data access volume and patterns) and flags significant deviations from that individual baseline — directly suited to catching account misuse via valid, stolen credentials that pass authentication but produce behavior inconsistent with the legitimate account owner''s established pattern.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ce28003b-7f98-4a10-948f-6385d2037231', '505ba1a6-943b-43b6-9ca6-e8b3c75e14aa', 1, 'MFA alone, since MFA continuously monitors ongoing account behavior after the initial login has already succeeded.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e00e08b-3fb6-4ad6-8fbc-b61269f15c20', '505ba1a6-943b-43b6-9ca6-e8b3c75e14aa', 2, 'A firewall, since firewalls establish per-user behavioral baselines and detect deviations in file-download volume and timing.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7a78bcb7-41ab-4002-9371-5edcb1881e57', '505ba1a6-943b-43b6-9ca6-e8b3c75e14aa', 3, 'Valid, stolen credentials that pass authentication cannot be detected by any security technology under any circumstance.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d40845f5-4e35-4956-807b-48466d0ce760', '9763cded-ba3d-4980-9407-804a10b057b0', 0, 'Order of volatility — evidence should generally be collected starting with the MOST volatile (most likely to be lost or changed quickly, like RAM contents, network connections, and running processes) and proceeding toward the LEAST volatile (like data on disk, which persists after power-off) — powering off the machine immediately, before capturing RAM, would permanently destroy exactly the evidence most at risk of loss.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c66a95f6-058f-4956-a93b-aa880b48185a', '9763cded-ba3d-4980-9407-804a10b057b0', 1, 'Evidence order does not matter at all during an investigation, since every type of evidence persists identically regardless of collection order.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c2296f19-fc76-48a8-8ba9-5cd72935ac78', '9763cded-ba3d-4980-9407-804a10b057b0', 2, 'Disk contents should always be captured before RAM, since disk data is more volatile and at greater risk of loss than RAM contents.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ee2adcf6-4b03-49af-b1d6-ddec44e8a057', '9763cded-ba3d-4980-9407-804a10b057b0', 3, 'RAM contents are never forensically useful and should be ignored entirely during any investigation.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('26021ab5-6b3e-4286-aac1-2b7149920594', '5602fdb1-4654-4ce4-b71b-73e022a78c36', 0, 'A tabletop exercise is a discussion-based simulation — walking through roles, decisions, and communication flows verbally/on paper WITHOUT touching real systems — valuable for testing whether the incident response PLAN and stakeholder coordination actually work in practice (revealing gaps like "who''s actually authorized to make the call to pay a ransom" before a real crisis), at much lower cost/risk/disruption than a live technical drill that actually exercises real systems and tooling.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4c4d445a-b714-4f75-952b-8e1967821db2', '5602fdb1-4654-4ce4-b71b-73e022a78c36', 1, 'Tabletop exercises and live technical drills are fully identical in method and value, with no meaningful distinction between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8ab94911-ca20-4d9f-9431-244017c270e0', '5602fdb1-4654-4ce4-b71b-73e022a78c36', 2, 'Tabletop exercises provide no value of any kind and should never be conducted, since only live production-system testing is worthwhile.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8a0fe3b7-5b7b-4f96-a14f-0463d12c20fc', '5602fdb1-4654-4ce4-b71b-73e022a78c36', 3, 'A tabletop exercise always requires taking real production systems offline, making it operationally identical to a live drill.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f20471c3-8aec-486d-b25d-847d14325ff9', 'd33af121-5b92-48fb-8be5-29d6f3c3da41', 0, 'SOAR (Security Orchestration, Automation, and Response), which lets a security team define automated "playbooks" for well-understood, repetitive response actions — triggered by alerts from tools like a SIEM or EDR — handling routine cases automatically while escalating genuinely ambiguous or high-severity situations to a human analyst.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('450641e8-d8f8-4b3c-af2d-65609aa5d127', 'd33af121-5b92-48fb-8be5-29d6f3c3da41', 1, 'A firewall alone, since firewalls automatically execute multi-step incident-response playbooks across multiple different security tools.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aa0a8b1c-6f0f-4b31-a00a-86de7c7bc6e5', 'd33af121-5b92-48fb-8be5-29d6f3c3da41', 2, 'AWS KMS, since KMS''s core function is automating security incident response playbooks.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f02e3d80-71b9-4698-a287-2bf0b303835c', 'd33af121-5b92-48fb-8be5-29d6f3c3da41', 3, 'No technology exists to automate any part of security incident response; every single response action must always be performed entirely manually.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6a583ced-21b3-4f48-b53a-c9ce590a28b9', 'c4d2896b-1f2f-4f91-bec8-702de220c579', 0, 'This is a genuine, real trade-off with no universally correct answer — factors include the severity/scope of ongoing harm the attacker could cause the longer they remain active (favoring faster containment), versus the intelligence value of understanding the full scope of what was accessed and the attacker''s techniques (favoring measured observation) — the decision should be made deliberately by incident response leadership based on the specific situation, not automatically defaulted to either extreme.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('af3fed87-4f5d-4d6a-ace6-4a00edf38a8b', 'c4d2896b-1f2f-4f91-bec8-702de220c579', 1, 'Containment should always happen immediately in every single case, with zero exception, regardless of any other factor or potential intelligence value.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5df04cb7-7673-4464-a12d-5e9016830dbe', 'c4d2896b-1f2f-4f91-bec8-702de220c579', 2, 'Observation should always continue indefinitely in every case, with containment never being the correct choice under any circumstance.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2d34962-2456-475b-8deb-91c138a1449a', 'c4d2896b-1f2f-4f91-bec8-702de220c579', 3, 'This decision is made entirely at random with no legitimate factors to consider.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ad5cc7bb-a0d8-43f5-bcc4-4c2e30605c0f', '1f6e47cc-0a65-48b9-81c5-02858931b5ea', 0, 'GDPR (General Data Protection Regulation) — a comprehensive EU data protection law with extraterritorial reach, meaning it can apply to any organization processing the personal data of EU residents regardless of where the organization itself is physically based or headquartered, specifically because the regulation is scoped to protect EU residents'' data wherever it''s processed, not just data processed by EU-based companies.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c7482a88-bfd6-4510-87f5-dd9f5f1207ad', '1f6e47cc-0a65-48b9-81c5-02858931b5ea', 1, 'HIPAA, since HIPAA is the EU''s data protection regulation with extraterritorial reach over non-EU companies.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fb32f522-3ccb-4f84-9cab-e33f9d123a7e', '1f6e47cc-0a65-48b9-81c5-02858931b5ea', 2, 'PCI-DSS, since PCI-DSS governs the personal data of EU residents specifically, regardless of payment card involvement.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9587499a-b7f8-4efa-a404-8cddf1709521', '1f6e47cc-0a65-48b9-81c5-02858931b5ea', 3, 'EU data protection law can never apply to any company physically based outside the EU under any circumstance.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7017a93d-332e-45fe-88a6-5d0756e7af49', '564eff40-1c97-413b-9fa7-2f282e1eed38', 0, 'A RACI matrix (Responsible, Accountable, Consulted, Informed) — explicitly assigns each of these four distinct roles to specific people or teams for a given task or decision, directly clarifying exactly who does the work (Responsible), who has final ownership/sign-off (Accountable), who must be asked for input beforehand (Consulted), and who simply needs to be notified afterward (Informed) — resolving exactly the kind of role confusion described.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('316c5e54-27e5-4195-a044-098331b79610', '564eff40-1c97-413b-9fa7-2f282e1eed38', 1, 'A Business Impact Analysis, since BIAs are the standard tool for assigning Responsible/Accountable/Consulted/Informed roles.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('22b76bf6-fa7b-471d-bab3-f7a65d08928b', '564eff40-1c97-413b-9fa7-2f282e1eed38', 2, 'An Acceptable Use Policy, since AUPs define which team members are accountable for specific project decisions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('824c5e91-609d-4abe-bd0c-9ae4d33ae137', '564eff40-1c97-413b-9fa7-2f282e1eed38', 3, 'No governance tool exists to clarify role confusion across multiple teams on a shared project.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f4df0c92-0bf9-4f97-be62-7f6c3f389257', '4dc6e807-dad0-427b-949c-6701e1650f76', 0, 'An evil twin attack — a rogue wireless access point deliberately configured with the same (or a very similar, easily-confused) SSID as a legitimate network, tricking nearby devices into connecting to the attacker''s access point instead of the real one, after which the attacker can intercept, monitor, or manipulate the victim''s traffic passing through it.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bc6d1cc4-ab3c-422f-95b7-d0684289e806', '4dc6e807-dad0-427b-949c-6701e1650f76', 1, 'A SQL injection attack, since SQL injection specifically describes broadcasting a duplicate wireless SSID to intercept nearby device traffic.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2ca8b54c-228c-41da-8eaf-0ea9235e7190', '4dc6e807-dad0-427b-949c-6701e1650f76', 2, 'A watering hole attack, since watering hole attacks are defined as broadcasting a rogue wireless access point with a duplicate SSID.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c474b572-28cf-4924-8d9c-c4ac33e4d74e', '4dc6e807-dad0-427b-949c-6701e1650f76', 3, 'This scenario is not a real attack technique, since wireless devices can never be tricked into connecting to the wrong access point.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1659dee2-5b77-48b2-a326-f638bd36e835', 'fdd18355-0709-4ad8-8bab-f13cd10c0b07', 0, 'A UPS (Uninterruptible Power Supply) — battery-backed equipment that instantly takes over supplying power the moment utility power is lost, with zero interruption to connected equipment, bridging the gap either until power is restored or (more commonly, for anything beyond a brief outage) until a generator has time to start and take over — distinct from a generator alone, which typically takes some seconds to start and cannot itself prevent that initial interruption.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('129fe057-7749-4e33-a63c-a9e5e6fb2147', 'fdd18355-0709-4ad8-8bab-f13cd10c0b07', 1, 'A firewall, since firewalls are the standard piece of infrastructure that provides battery-backed, uninterrupted power during a utility outage.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e63879ce-d0bb-4e62-9307-faa9dd9b4199', 'fdd18355-0709-4ad8-8bab-f13cd10c0b07', 2, 'A VPN concentrator, since VPN concentrators bridge the gap between utility power loss and generator startup with zero interruption.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('78666594-2e29-4b66-a881-803b324eebb9', 'fdd18355-0709-4ad8-8bab-f13cd10c0b07', 3, 'No infrastructure exists that can provide power during the moment utility power is first lost; some interruption is always unavoidable.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('19811cb5-e3b9-43ce-a1b9-1427436bf9db', '39797df0-45ce-49d1-bf0c-007aaec16854', 0, 'A playbook (or runbook) — a standardized, step-by-step written procedure for handling a SPECIFIC, recurring type of security event or task consistently and completely regardless of which analyst is on shift, distinct from a broader incident response POLICY (which sets overall goals/authority) or PLAN (which covers the general incident lifecycle) by being concretely actionable for one specific scenario.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ac66b1db-3c24-433e-916b-05db339794db', '39797df0-45ce-49d1-bf0c-007aaec16854', 1, 'An Acceptable Use Policy, since AUPs are the standard document type for standardized, step-by-step response procedures to specific recurring security events.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('da6a662a-76b7-4649-975f-f075b71910eb', '39797df0-45ce-49d1-bf0c-007aaec16854', 2, 'A Business Impact Analysis, since BIAs provide step-by-step response procedures for specific recurring security event types.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fcd25b8a-0cde-46cb-9930-c6195548e7ea', '39797df0-45ce-49d1-bf0c-007aaec16854', 3, 'Standardizing incident response steps in writing provides no operational value and is not a real practice.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c887d74e-b243-4611-b8ed-569c4779a135', 'f45f14b2-b8e0-4423-af39-8bdc63a2ffec', 0, 'A lessons-learned review (post-incident review / retrospective) — conducted after an incident is fully resolved, deliberately structured as blameless so participants are honest about what actually happened (including their own mistakes) rather than defensive, with the goal of extracting concrete, actionable improvements to detection, response, or prevention for next time.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f39efb3f-d6cf-4713-a53c-2758d805d60e', 'f45f14b2-b8e0-4423-af39-8bdc63a2ffec', 1, 'Containment, since containment is the final incident-response phase, occurring after full resolution rather than during active response.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7e4604fb-3daa-4664-a0c0-341b53054df0', 'f45f14b2-b8e0-4423-af39-8bdc63a2ffec', 2, 'Eradication, since eradication is defined as a blameless meeting held after incident resolution to document lessons learned.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ce303d2b-4f17-429b-843d-81278eab04b6', 'f45f14b2-b8e0-4423-af39-8bdc63a2ffec', 3, 'Reviewing an incident after it''s resolved provides no value, since the incident is already over by that point.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7b170d47-b237-4a0f-a45d-914dd2c239a5', '5d8d872f-e4b7-4789-b0fe-82f4849f07b8', 0, 'Vendor risk assessment (part of third-party/supply-chain risk management) — formally evaluating a prospective vendor''s actual security practices (e.g., reviewing their security certifications, requesting audit reports like a SOC 2, or running a dedicated security questionnaire) BEFORE granting them access to company data or systems, rather than relying solely on the vendor''s own unverified claims.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('30b76806-8c69-4e32-a8aa-6a130bf9ccd7', '5d8d872f-e4b7-4789-b0fe-82f4849f07b8', 1, 'A tabletop exercise, since tabletop exercises are specifically the process for formally verifying a prospective vendor''s security practices before contract signing.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('41d21323-85c9-4255-be20-006ecb80788f', '5d8d872f-e4b7-4789-b0fe-82f4849f07b8', 2, 'File Integrity Monitoring, since FIM is used to verify a vendor''s security posture before a contract is signed.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('375fb8d7-f4e0-400c-be5e-913c339b0553', '5d8d872f-e4b7-4789-b0fe-82f4849f07b8', 3, 'Once a vendor is contractually engaged, no verification of their security practices is possible or necessary at any point.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('807f077b-51ad-46bf-9195-bbb191630a80', 'a7180e92-c5e3-4087-9497-0e18f9e18cd9', 0, 'This is a policy exception (or policy violation, depending on whether it was formally approved) — a genuine deviation from established policy should either go through a FORMAL exception process (documented, risk-assessed, and approved by an appropriate authority, often with compensating controls and a defined expiration) BEFORE the deviation happens, or if it already happened without approval, be identified and addressed through governance/oversight rather than quietly allowed to stand unaddressed.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d7d1c271-0937-4700-89e4-e820dc40cc5f', 'a7180e92-c5e3-4087-9497-0e18f9e18cd9', 1, 'This situation requires no governance response of any kind, since deadline pressure automatically and permanently overrides any documented security policy without any further process.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('295037c6-d4cb-4f1e-a7fb-5f46180977be', 'a7180e92-c5e3-4087-9497-0e18f9e18cd9', 2, 'This is a Business Impact Analysis, since BIAs are defined as informal, undocumented deviations from established security policy.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('924c93c3-2a3e-493c-9dee-3146120409cb', 'a7180e92-c5e3-4087-9497-0e18f9e18cd9', 3, 'Documented security policies are purely aspirational and are never actually expected to be followed by any business unit under real deadline pressure.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
